U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
def fetch(s):
    for fn in (get_index_daily_data,get_stock_daily_data):
        try:
            d=fn(s,3000)
            if d is not None and len(d):
                d=d.copy(); d.date=pd.to_datetime(d.date).dt.normalize()
                return d.drop_duplicates('date').set_index('date').sort_index()
        except Exception: pass
    return None
D={s:fetch(s) for s in U}; D={s:d for s,d in D.items() if d is not None}
rows=[]
for s,d in D.items():
    c=d.close.astype(float); r=c.pct_change()
    mom=c.pct_change(30).shift(1)
    persistence=r.gt(0).rolling(20,min_periods=15).mean().shift(1)
    vol=r.rolling(30,min_periods=20).std().shift(1)
    f=mom/(vol+1e-12)*persistence
    rows.append(pd.DataFrame({'date':c.index,'asset':s,'f':f,'fr':c.shift(-10)/c-1}))
q=pd.concat(rows,ignore_index=True).replace([np.inf,-np.inf],np.nan).dropna()
def stat(x):
    z=[]; ns=[]
    for _,g in x.groupby('date'):
        if len(g)>=8 and g.f.nunique()>1 and g.fr.nunique()>1:
            z.append(g.f.corr(g.fr,method='spearman')); ns.append(len(g))
    z=pd.Series(z)
    return len(z),float(np.mean(ns)),float(z.mean()),float(z.mean()/z.std(ddof=1)*np.sqrt(252)),float((z>0).mean())
latest=q.date.max(); recent=q[q.date>=latest-pd.Timedelta(days=365)]
print('assets',len(D),'latest',latest.date(),'full_dates',q.date.nunique(),'recent_dates',recent.date.nunique(),'full',stat(q),'recent',stat(recent))
for a,b in [(2020,2022),(2023,2024),(2025,2026),(2027,2028)]:
 x=q[(q.date.dt.year>=a)&(q.date.dt.year<=b)]
 if len(x): print('regime',a,b,stat(x))
r=q.pivot(index='date',columns='asset',values='f').rank(axis=1,pct=True)
print('coverage',len(q)/(q.date.nunique()*15),'turnover',r.diff().abs().mean().mean())
