        for lab,lo,hi in [('2020-22','2020','2022-12-31'),('2023-24','2023','2024-12-31'),('2025-26','2025','2026-12-31'),('2027-28','2027','2028-12-31')]:
            q=a[[pd.Timestamp(lo)<=x<=pd.Timestamp(hi) for x in dates]]
