breadth=(raw>0).mean(axis=1)
regime=np.where(breadth<0.40,-1.0,1.0)
sig=(raw.sub(raw.median(axis=1),axis=0)/(vol*np.sqrt(20)+1e-8)*regime[:,None]).shift(1).rank(axis=1,pct=True)
for h in (1,5,10,20):
