# lag every input: decision date i uses data through i-1
f=(-(mom/(vol.replace(0,np.nan))).sub((mom/vol.replace(0,np.nan)).mean(axis=1),axis=0) * (0.5+breadth.shift(1).clip(upper=.5))).shift(1)
# activate at broader selloff threshold; otherwise neutral zero
f=f.where(breadth.shift(1)<=.40,0.0)
rows=[]; ics=[]
