R={h:[] for h in [1,5,10,20]}; cov=[]; turn=[]; prev=None; rows=[]
Ds=sorted(set().union(*[set(x.index[x.index<=cutoff]) for x in D.values()]))
for t in Ds:
 a={}; F={h:{} for h in R}
 for s,x in D.items():
  if t not in x.index: continue
  z=x.loc[:t]; c=z.close.astype(float)
  if len(z)<125: continue
  r60=c.iloc[-1]/c.iloc[-61]-1; vol60=np.log(c/c.shift(1)).rolling(60).std().iloc[-1]; r20=c.iloc[-1]/c.iloc[-21]-1
  if not np.all(np.isfinite([r60,vol60,r20])) or vol60<=0: continue
