import pandas as pd, numpy as np
from scipy.stats import spearmanr
assets=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
base='../persistent/stock_data'; px={}
for a in assets:
 d=pd.read_csv(f'{base}/{a}.csv',parse_dates=['date']).set_index('date')['close'].astype(float); px[a]=d
p=pd.DataFrame(px).sort_index(); macro=pd.read_csv('../persistent/index_data/VIX.csv',parse_dates=['date']).set_index('date')['close'].astype(float).reindex(p.index).ffill(); r=p.pct_change()
mom=p.pct_change(20); vol=r.rolling(40).std()*np.sqrt(252); vr=macro.rolling(60,min_periods=30).rank(pct=True)
f=mom.div(vol).mul(np.where(vr.values[:,None]>.70,-0.5,1.0),axis=0)
for h in [5,10,20]:
 fr=p.shift(-h).div(p)-1; ics=[]; cov=[]; ns=[]
 for dt in p.index:
  x=f.loc[dt]; y=fr.loc[dt]; ok=x.notna()&y.notna()
  if ok.sum()>=8:
   ics.append(spearmanr(x[ok],y[ok]).statistic); cov.append(ok.mean()); ns.append(ok.sum())
 z=pd.Series(ics).dropna(); turns=[]
 for i in range(1,len(p)):
  a=f.iloc[i].rank(pct=True); b=f.iloc[i-1].rank(pct=True); turns.append((a-b).abs().mean())
 print('H',h,'obs',len(z),'avgN',round(np.mean(ns),2),'IC',round(z.mean(),6),'ICIR',round(z.mean()/z.std(ddof=1),6),'hit',round((z>0).mean(),4),'coverage',round(np.mean(cov),4),'turnover',round(np.mean(turns),4),'period',p.index.min().date(),p.index.max().date())

import os, numpy as np, pandas as pd
from alphacrafter.sim.utils import get_index_daily_data, get_stock_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
def fetch(s):
    for fn in (get_index_daily_data,get_stock_daily_data):
        try:
            x=fn(symbol=s,days=6000)
            if x is not None and len(x)>100:return x[['date','close']]
        except Exception: pass
D={s:fetch(s) for s in U}; D={s:x for s,x in D.items() if x is not None}
px=pd.concat([x.set_index('date').close.rename(s) for s,x in D.items()],axis=1).sort_index()
px=px.replace([np.inf,-np.inf],np.nan).where(lambda z:z>0)
r=np.log(px).diff(); r5=np.log(px/px.shift(5)); vol=r.rolling(20,min_periods=15).std()
csmean=r5.mean(axis=1); resid=r5.sub(csmean,axis=0); disp=r.std(axis=1).rolling(5,min_periods=5).mean(); threshold=disp.rolling(120,min_periods=60).median()
f=(-resid/vol).where(disp>threshold)
fr=np.log(px.shift(-20)/px).replace([np.inf,-np.inf],np.nan)
rows=[]; sig=[]
for dt in f.index:
 a=f.loc[dt]; b=fr.loc[dt]; ok=a.notna()&b.notna()
 if ok.sum()>=8:
  c=a[ok].corr(b[ok])
  if np.isfinite(c):rows.append((dt,c,int(ok.sum())))
 for s in a[a.notna()].index:sig.append({'date':str(dt.date()),'symbol':s,'signal':float(a[s])})
q=pd.DataFrame(rows,columns=['date','ic','n'])
print('universe',len(D),'dates',len(q),'date_range',q.date.min(),q.date.max(),'avg_n',q.n.mean())
print('IC %.8f ICIR %.8f hit %.4f recent500 %.8f'%(q.ic.mean(),q.ic.mean()/q.ic.std(ddof=1),(q.ic>0).mean(),q.tail(500).ic.mean()))
coverage=np.mean([f.loc[d].notna().sum()/len(U) for d in q.date]);print('coverage %.4f'%coverage)
for lo,hi in [('2020','2024'),('2025','2029'),('2030','2034'),('2035','2035')]:
 z=q[(q.date.astype(str)>=lo)&(q.date.astype(str)<=hi)]
 if len(z):print('regime',lo,hi,len(z),'IC %.6f ICIR %.4f'%(z.ic.mean(),z.ic.mean()/z.ic.std(ddof=1)))
os.makedirs('scripts',exist_ok=True);pd.DataFrame(sig).to_csv('scripts/miner_1_20350903_residual_dispersion_reversal_signal.csv',index=False);print('signal_rows',len(sig))

# Reuse the residual-dispersion reversal construction and compare forward horizons.
exec(open('scripts/miner_1_20350903_residual_dispersion_reversal.py').read().split("fr=np.log(px.shift(-20)/px)")[0])
for h in (5,10,20):
 fr=np.log(px.shift(-h)/px).replace([np.inf,-np.inf],np.nan); vals=[]
 for dt in f.index:
  a=f.loc[dt]; b=fr.loc[dt]; ok=a.notna()&b.notna()
  if ok.sum()>=8:
   c=a[ok].corr(b[ok])
   if np.isfinite(c): vals.append(c)
 q=np.array(vals); print('horizon',h,'observations',len(q),'IC %.8f ICIR %.8f hit %.4f'%(q.mean(),q.mean()/q.std(ddof=1),np.mean(q>0)))

